  local dst="$2"
  mkdir -p "$(dirname "$dst")"
  cp -a "$src" "$dst"
}

main() {
  if [[ $# -ne 2 ]]; then
    echo "usage: $0 <src> <dst>" >&2
    exit 2
  fi
  backup "$1" "$2"
}

main "$@"

